const now = new Date();
const currentMonth = now.getMonth();
const year = now.getFullYear();

const arabicMonths = ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'];

function toArabicNumerals(num) {
  const arabicNumerals = ['٠', '١', '٢', '٣', '٤', '٥', '٦', '٧', '٨', '٩'];
  return num.toString().split('').map(d => arabicNumerals[parseInt(d)] || d).join('');
}

let half, halfArabic, startMonth, endMonth, reportYear;

if (currentMonth === 0) {
  half = 2; halfArabic = 'الثاني'; startMonth = 6; endMonth = 11; reportYear = year - 1;
} else if (currentMonth === 6) {
  half = 1; halfArabic = 'الأول'; startMonth = 0; endMonth = 5; reportYear = year;
} else {
  half = currentMonth < 6 ? 2 : 1;
  halfArabic = half === 1 ? 'الأول' : 'الثاني';
  startMonth = half === 1 ? 0 : 6;
  endMonth = half === 1 ? 5 : 11;
  reportYear = half === 2 && currentMonth < 6 ? year - 1 : year;
}

const startDate = `${reportYear}-${String(startMonth + 1).padStart(2, '0')}-01`;
const endDate = new Date(reportYear, endMonth + 1, 0).toISOString().split('T')[0];
const fileName = `تقرير_نصف_سنوي_${reportYear}-H${half}.docx`;

return {
  json: {
    half: half,
    half_arabic: halfArabic,
    year: reportYear,
    year_arabic: toArabicNumerals(reportYear),
    start_month: arabicMonths[startMonth],
    end_month: arabicMonths[endMonth],
    start_date: startDate,
    end_date: endDate,
    file_name: fileName,
    report_title: `التقرير نصف السنوي - النصف ${halfArabic} ${toArabicNumerals(reportYear)}`,
    years_comparison: [reportYear, reportYear - 1, reportYear - 2]
  }
};

