const reportData = $input.first().json;
const htmlContent = `<!DOCTYPE html><html dir="rtl" lang="ar"><head><meta charset="UTF-8"><style>body{font-family:'Arial',sans-serif;direction:rtl;text-align:right;line-height:1.8;padding:40px;max-width:800px;margin:0 auto}h1,h2{color:#1a365d;border-bottom:2px solid #2c5282;padding-bottom:10px}pre{white-space:pre-wrap;font-family:'Arial',sans-serif}</style></head><body><pre>${reportData.report_content}</pre></body></html>`;
return { json: { ...reportData, html_content: htmlContent }, binary: { report_html: { data: Buffer.from(htmlContent).toString('base64'), mimeType: 'text/html', fileName: reportData.file_name.replace('.docx', '.html') } } };
